#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int sai = 0, chan = 0;
    for (int i = 1; i <= n; i++) {
        int x;
        scanf("%d", &x);
        if (sai >= 30 && !chan) { chan = i; }
        if (x == 1) sai++;
    }
    printf("%d\n", chan);
    return 0;
}
